window.BorefieldDutch.dynamic=function(s,t){let m;if((m=s.match(/^Recalculating depth (.+) m…$/)))return 'Diepte '+m[1]+' m opnieuw berekenen…';if((m=s.match(/^(\w+) ground injection, kWh$/)))return t(m[1])+' warmte-injectie in de bodem, kWh';if((m=s.match(/^Loop ΔT: (.+) K monthly; (.+) K at the largest modelled peak\.$/)))return 'Lus-ΔT: '+m[1]+' K per maand; '+m[2]+' K bij de grootste berekende piek.';if((m=s.match(/^Annual ground injection: (.+) kWh\. Final-year extraction: (.+) kWh\. Net extraction: (.+) kWh\. Additional regeneration electricity: (.+) kWh\/year\. No cooling benefit is credited against gas\.$/)))return `Jaarlijkse warmte-injectie: ${m[1]} kWh. Onttrekking in laatste jaar: ${m[2]} kWh. Netto-onttrekking: ${m[3]} kWh. Extra regeneratiestroom: ${m[4]} kWh/jaar. Koeling krijgt geen financiële waarde tegenover gas.`;return priorDutchDynamic(s,t);};
